    add('IPtProxy-master','kindness-runtime','Snowflake proxy kindness runtime','IPtProxy.go/kindness.go','mechanism comparison','reference-only','Volunteer proxy/runtime authority is not added to LumiNet; only client admission semantics are used.','PT client planning','src/apps/daemon/internal/analysis/diagnostics/pluggable_transport_plan.go','scripts/checks/check_post_refactor_231_convergence.py',surface='governance',status='reviewed')
