def main():
    OUT.mkdir(parents=True,exist_ok=True)
    surfaces=sorted(read_csv(RAW/'surface_accountability_raw.csv'),key=lambda r:(r['donor'],r['path']))
    dirs=sorted(read_csv(RAW/'directory_merkle_raw.csv'),key=lambda r:(r['donor'],r['directory']))
    defs=sorted(read_csv(RAW/'definition_index_raw.csv'),key=lambda r:(r['donor'],r['path'],int(r['line']),r['kind'],r['symbol']))
    syms=sorted(read_csv(RAW/'symlinks_normalized_raw.csv'),key=lambda r:(r['donor'],r['path']))
    archives=sorted(read_csv(RAW/'archive_summary_raw.csv'),key=lambda r:r['archive'])
    shutil.copyfile(BASELINE,OUT/'post-refactor-231-baseline-files.csv')
    groups=defaultdict(list)
    for r in surfaces:groups[(r['donor'],r['module'])].append(r)
    modules=sorted(groups)
    repo_id={d:f'PR231-R{i:03d}' for i,d in enumerate(sorted(DONORS),1)}
    mod_id={k:f'PR231-M{i:04d}' for i,k in enumerate(modules,1)}
    file_id={(r['donor'],r['path']):f'PR231-F{i:05d}' for i,r in enumerate(surfaces,1)}
    focus=focus_specs(); focus_id={i:f'PR231-S{i+1:03d}' for i in range(len(focus))}; focus_by_path=defaultdict(list)
    for i,f in enumerate(focus):
        f['sha256']=donor_file_sha(f['donor'],f['path']);focus_by_path[(f['donor'],f['path'])].append(focus_id[i])
        for n in f['nodes'].split(';'):
            p=n.split('#',1)[0]
            if p and p!='n/a' and not (ROOT/p).exists() and not p.startswith('governance/convergence/post-refactor-231-'):raise FileNotFoundError(f'target node {p}')
        tp=f['test'].split('#',1)[0]
        if tp!='n/a' and not (ROOT/tp).exists() and tp!='scripts/checks/check_post_refactor_231_convergence.py':raise FileNotFoundError(f'test node {tp}')
    ledger=[]; first_by=defaultdict(list)
    for r in surfaces:first_by[r['donor']].append(r)
    for d in sorted(DONORS):
        rep=sorted(first_by[d],key=lambda x:x['path'])[0]
        ledger.append(dict(record_id=repo_id[d],parent_record_id='n/a',composition_group_id=f'CG231-{d}-root',donor=d,domain='repository-accountability',value_unit=f'{d} complete archive/repository accountability',source_granularity='repository',value_form='evidence corpus',separability='context-dependent',donor_path=rep['path'],donor_sha256=rep['sha256'],donor_symbol='n/a',transformation='exhaustive evidence review',mapping_topology='one-to-many',disposition='reference-only',decision_rationale='Every archive member, regular file, normalized directory, indexed donor-authored definition, and archived symlink is accounted before behavior-level selection.',target_capability='convergence evidence',target_nodes='governance/convergence/post-refactor-231-surface-accountability.csv',invariant='all donor bytes remain attributable to exact source hashes',negative_invariant='vendor mass or repository popularity cannot grant target authority',test_node='scripts/checks/check_post_refactor_231_convergence.py',operator_surface='governance/convergence',migration_impact='none',license_note='source provenance retained; no bulk donor import',risk_tier='low',dependency_record_ids='n/a',evidence_confidence='high',validation_status='reviewed'))
    module_rows=[]
    for key in modules:
        d,m=key;rows=groups[key];high=sum(x['classification'] in HIGH for x in rows);ui=sum(x['classification']=='ui-or-product' for x in rows);impl=sum(x['classification']=='implementation' for x in rows);tests=sum(x['classification']=='test' for x in rows)
        focused=sorted({fid for r in rows for fid in focus_by_path.get((d,r['path']),[])})
        disp='behavior-refined' if focused else ('reviewed-superseded-or-reference' if high else 'accounted-reference')
        rep=sorted(rows,key=lambda x:x['path'])[0]
        ledger.append(dict(record_id=mod_id[key],parent_record_id=repo_id[d],composition_group_id=f'CG231-{d}-{sha_text(m)[:10]}',donor=d,domain='module-accountability',value_unit=f'{m} module/subtree review',source_granularity='module/subtree',value_form='mixed evidence',separability='module-cohesive',donor_path=rep['path'],donor_sha256=rep['sha256'],donor_symbol='n/a',transformation='mechanism-level review',mapping_topology='many-to-many',disposition=disp,decision_rationale=f'{len(rows)} surfaces reviewed; {high} high-signal, {ui} product/UI, {tests} tests. Focused behavior records split independent semantics where applicable.',target_capability='convergence evidence or target-native owner',target_nodes='governance/convergence/post-refactor-231-adoption-ledger.csv',invariant='module-level context preserved around per-file decisions',negative_invariant='umbrella records cannot hide unresolved high-signal files',test_node='scripts/checks/check_post_refactor_231_convergence.py',operator_surface='governance/convergence',migration_impact='none unless focused records say otherwise',license_note='no module copied wholesale',risk_tier='medium' if high else 'low',dependency_record_ids=repo_id[d],evidence_confidence='high',validation_status='reviewed'))
        payload='\n'.join(f"{r['path']}\0{r['sha256']}\0{r['classification']}" for r in sorted(rows,key=lambda x:x['path']))
        module_rows.append(dict(wave='231',donor=d,module=m,surfaces=len(rows),high_signal_surfaces=high,ui_product_surfaces=ui,implementation_surfaces=impl,test_surfaces=tests,layers=';'.join(sorted({r['classification'] for r in rows})),current_outcome=disp,current_product_surfaces='Operations/Settings where focused; otherwise governance',surface_sha256=sha_text(payload)))
    out_surfaces=[]
    for r in surfaces:
        d,p=r['donor'],r['path'];key=(d,r['module']);fids=focus_by_path.get((d,p),[]);rid=file_id[(d,p)]
        disp='focused-behavior-source' if fids else ('reviewed-superseded-or-reference' if r['classification'] in HIGH else 'accounted-reference')
        ledger.append(dict(record_id=rid,parent_record_id=mod_id[key],composition_group_id=f'CG231-file-{rid}',donor=d,domain='file-accountability',value_unit=f'{p} per-file review',source_granularity='file',value_form=r['classification'],separability='file-contextual',donor_path=p,donor_sha256=r['sha256'],donor_symbol='n/a',transformation='fresh byte revalidation and contextual review',mapping_topology='one-to-many',disposition=disp,decision_rationale='Exact bytes are accounted and reviewed in module context; independently promoted/rejected mechanisms are linked through focused behavior records.',target_capability='convergence evidence',target_nodes='governance/convergence/post-refactor-231-surface-accountability.csv',invariant='file hash and classification remain traceable',negative_invariant='per-file accounting is not itself behavioral equivalence',test_node='scripts/checks/check_post_refactor_231_convergence.py',operator_surface='governance/convergence',migration_impact='none',license_note='no bulk source import',risk_tier='medium' if r['classification'] in HIGH else 'low',dependency_record_ids=mod_id[key],evidence_confidence='high',validation_status='reviewed'))
        x=dict(r);x['semantic_record_ids']=';'.join([rid,mod_id[key]]+fids);x['post_refactor_231_review']='fresh-byte-reverified-and-context-reviewed';x['post_refactor_231_disposition']=disp;x['notes']='Focused semantic record linked.' if fids else 'Exhaustive per-file accountability; module decision retained.';out_surfaces.append(x)
    for i,f in enumerate(focus):
        rid=focus_id[i];parent=file_id[(f['donor'],f['path'])]
        ledger.append(dict(record_id=rid,parent_record_id=parent,composition_group_id=f"CG231-{f['domain'].replace('/','-')}",donor=f['donor'],domain=f['domain'],value_unit=f['value'],source_granularity='behavior/primitive',value_form=f['form'],separability='independently meaningful',donor_path=f['path'],donor_sha256=f['sha256'],donor_symbol='n/a',transformation=f['transformation'],mapping_topology='many-to-many',disposition=f['disposition'],decision_rationale=f['rationale'],target_capability=f['capability'],target_nodes=f['nodes'],invariant=f['invariant'],negative_invariant=f['negative'],test_node=f['test'],operator_surface=f['surface'],migration_impact='additive or none; existing authority retained',license_note='target-native semantics; donor provenance retained',risk_tier=f['risk'],dependency_record_ids=parent,evidence_confidence='high',validation_status=f['status']))
    archive_rows=[dict(donor=r['donor'],archive=r['archive'],sha256=r['archive_sha256'],members=r['members'],regular_files=r['files'],directories=r['directories'],symlinks=r['symlinks'],uncompressed_bytes=r['payload_bytes'],admission_status='validated-before-extraction',path_safety='verified',crc='verified',nested_like_members=r.get('nested_like_members','')) for r in archives]
    write_csv(OUT/'post-refactor-231-archive-accountability.csv',archive_rows,['donor','archive','sha256','members','regular_files','directories','symlinks','uncompressed_bytes','admission_status','path_safety','crc','nested_like_members'])
    sf=list(surfaces[0].keys())+['semantic_record_ids','post_refactor_231_review','post_refactor_231_disposition','notes']
    write_csv(OUT/'post-refactor-231-surface-accountability.csv',out_surfaces,sf)
    write_csv(OUT/'post-refactor-231-directories.csv',dirs,list(dirs[0].keys()))
    write_csv(OUT/'post-refactor-231-symbols.csv',defs,list(defs[0].keys()))
    write_csv(OUT/'post-refactor-231-symlinks.csv',syms,list(syms[0].keys()))
    write_csv(OUT/'post-refactor-231-module-audit.csv',module_rows,list(module_rows[0].keys()))
    write_csv(OUT/'post-refactor-231-adoption-ledger.csv',ledger,LEDGER_FIELDS)
    supers=[dict(donor=f['donor'],donor_path=f['path'],value_unit=f['value'],donor_outcome=f['disposition'],target_owner=f['nodes'],reason=f['rationale'],guardrail=f['negative']) for f in focus if f['disposition'] in {'rejected','superseded','hardened','adapted'}]
    write_csv(OUT/'post-refactor-231-supersession-map.csv',supers,['donor','donor_path','value_unit','donor_outcome','target_owner','reason','guardrail'])
    prev_s=read_csv(OUT/'post-refactor-230-all-history-surface-audit.csv');hist_s=list(prev_s)
    for r in out_surfaces:hist_s.append(dict(wave='231',donor=r['donor'],path=r['path'],sha256=r['sha256'],size_bytes=r['size_bytes'],classification=r['classification'],source_layer=r['module'],semantic_record_ids=r['semantic_record_ids'],original_disposition=r['post_refactor_231_disposition'],current_target_layer='target-native planner/guardrail or governance evidence',cross_wave_outcome=r['post_refactor_231_disposition'],current_product_surface='Convergence policy lab / Settings / governance'))
    write_csv(OUT/'post-refactor-231-all-history-surface-audit.csv',hist_s,list(prev_s[0].keys()))
    prev_d=read_csv(OUT/'post-refactor-230-all-history-symbol-index.csv');hist_d=list(prev_d);surface_ids={(r['donor'],r['path']):r['semantic_record_ids'] for r in out_surfaces}
